window.SHADERTOY_SHADERS = {"fire":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// Rising flame: shape mask + domain-warped fBm + heat ramp.\n\nfloat hash12(vec2 p) {\n  vec3 p3 = fract(vec3(p.xyx) * 0.1031);\n  p3 += dot(p3, p3.yzx + 33.33);\n  return fract((p3.x + p3.y) * p3.z);\n}\n\nfloat noise(vec2 p) {\n  vec2 i = floor(p), f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1,0)), u.x),\n             mix(hash12(i + vec2(0,1)), hash12(i + vec2(1,1)), u.x), u.y);\n}\n\nfloat fbm(vec2 p) {\n  float v = 0.0, a = 0.5;\n  mat2 m = mat2(1.6, 1.2, -1.2, 1.6);\n  for (int i = 0; i < 5; i++) { v += a * noise(p); p = m * p; a *= 0.5; }\n  return v;\n}\n\nvec3 fireRamp(float x) {\n  x = clamp(x, 0.0, 1.0);\n  vec3 c = vec3(0.0);\n  c = mix(c, vec3(0.35, 0.02, 0.0), smoothstep(0.05, 0.22, x));\n  c = mix(c, vec3(0.85, 0.12, 0.02), smoothstep(0.18, 0.42, x));\n  c = mix(c, vec3(1.00, 0.45, 0.05), smoothstep(0.38, 0.62, x));\n  c = mix(c, vec3(1.00, 0.85, 0.35), smoothstep(0.58, 0.82, x));\n  c = mix(c, vec3(1.00, 0.98, 0.90), smoothstep(0.78, 1.00, x));\n  return c;\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;\n  float wind = (iMouse.z > 0.0) ? (iMouse.x / iResolution.x - 0.5) * 0.8 : 0.15 * sin(iTime * 0.7);\n  vec2 q = p + vec2(wind * (p.y + 0.6), 0.0);\n  float shape = 1.0 - length(vec2(q.x * 2.1, (q.y + 0.15) * 0.72));\n  shape = smoothstep(0.0, 0.55, shape);\n  vec2 nUv = vec2(q.x * 3.0, q.y * 4.2 - iTime * 1.6);\n  nUv.x += 0.55 * fbm(nUv + iTime * 0.25);\n  float n = fbm(nUv);\n  float flame = n * shape;\n  flame = pow(max(flame, 0.0), 1.15);\n  vec3 col = fireRamp(flame);\n  float smoke = fbm(vec2(q.x * 2.0, q.y * 1.4 - iTime * 0.35)) * smoothstep(-0.1, 0.6, q.y) * (1.0 - shape);\n  col += vec3(0.12, 0.12, 0.14) * smoke * 0.55;\n  col *= 0.25 + 0.75 * smoothstep(-0.7, 0.2, p.y);\n  fragColor = vec4(col, 1.0);\n}\n","campfire":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// Campfire: ground, logs, glow, and a smaller flame.\n\nfloat hash12(vec2 p) {\n  vec3 p3 = fract(vec3(p.xyx) * 0.1031);\n  p3 += dot(p3, p3.yzx + 33.33);\n  return fract((p3.x + p3.y) * p3.z);\n}\nfloat noise(vec2 p) {\n  vec2 i = floor(p), f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1,0)), u.x),\n             mix(hash12(i + vec2(0,1)), hash12(i + vec2(1,1)), u.x), u.y);\n}\nfloat fbm(vec2 p) {\n  float v = 0.0, a = 0.5;\n  mat2 m = mat2(1.6, 1.2, -1.2, 1.6);\n  for (int i = 0; i < 5; i++) { v += a * noise(p); p = m * p; a *= 0.5; }\n  return v;\n}\nfloat sdCapsule(vec2 p, vec2 a, vec2 b, float r) {\n  vec2 pa = p - a, ba = b - a;\n  float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);\n  return length(pa - ba * h) - r;\n}\nvec3 fireRamp(float x) {\n  x = clamp(x, 0.0, 1.0);\n  vec3 c = mix(vec3(0.0), vec3(0.8, 0.1, 0.0), smoothstep(0.1, 0.35, x));\n  c = mix(c, vec3(1.0, 0.5, 0.05), smoothstep(0.3, 0.6, x));\n  return mix(c, vec3(1.0, 0.95, 0.7), smoothstep(0.55, 0.95, x));\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;\n  vec3 sky = mix(vec3(0.02, 0.03, 0.06), vec3(0.08, 0.05, 0.04), smoothstep(-0.2, 0.8, p.y));\n  float ground = smoothstep(0.01, -0.02, p.y + 0.32);\n  vec3 col = mix(sky, vec3(0.05, 0.04, 0.03), ground);\n\n  float log1 = sdCapsule(p, vec2(-0.22, -0.30), vec2(0.20, -0.26), 0.035);\n  float log2 = sdCapsule(p, vec2(-0.16, -0.24), vec2(0.24, -0.34), 0.03);\n  float logs = min(log1, log2);\n  col = mix(col, vec3(0.12, 0.07, 0.04), 1.0 - smoothstep(0.0, 0.008, logs));\n\n  vec2 q = p - vec2(0.0, -0.18);\n  float shape = 1.0 - length(vec2(q.x * 2.6, q.y * 1.1));\n  shape = smoothstep(0.0, 0.5, shape);\n  vec2 nUv = vec2(q.x * 4.0, q.y * 5.0 - iTime * 1.8);\n  nUv.x += 0.45 * fbm(nUv);\n  float flame = pow(max(fbm(nUv) * shape, 0.0), 1.2);\n  col += fireRamp(flame);\n\n  float glow = exp(-8.0 * length(p - vec2(0.0, -0.22)));\n  col += vec3(1.0, 0.35, 0.05) * glow * 0.35;\n  fragColor = vec4(col, 1.0);\n}\n","lava":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// Lava: dark crust, glowing cracks, slow domain warp.\n\nfloat hash12(vec2 p) {\n  vec3 p3 = fract(vec3(p.xyx) * 0.1031);\n  p3 += dot(p3, p3.yzx + 33.33);\n  return fract((p3.x + p3.y) * p3.z);\n}\nfloat noise(vec2 p) {\n  vec2 i = floor(p), f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1,0)), u.x),\n             mix(hash12(i + vec2(0,1)), hash12(i + vec2(1,1)), u.x), u.y);\n}\nfloat fbm(vec2 p) {\n  float v = 0.0, a = 0.5;\n  mat2 m = mat2(1.6, 1.2, -1.2, 1.6);\n  for (int i = 0; i < 6; i++) { v += a * noise(p); p = m * p; a *= 0.5; }\n  return v;\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 uv = fragCoord / iResolution.xy;\n  vec2 p = uv * vec2(iResolution.x / iResolution.y, 1.0) * 3.0;\n  p += 0.35 * vec2(fbm(p + iTime * 0.08), fbm(p + 4.2 - iTime * 0.06));\n  float n = fbm(p);\n  float ridge = 1.0 - abs(n * 2.0 - 1.0);\n  float crack = smoothstep(0.55, 0.92, ridge);\n  vec3 crust = mix(vec3(0.04, 0.03, 0.03), vec3(0.12, 0.06, 0.04), n);\n  vec3 glow = mix(vec3(0.6, 0.05, 0.0), vec3(1.0, 0.7, 0.15), pow(crack, 2.0));\n  vec3 col = mix(crust, glow, crack);\n  col += glow * 0.25 * crack;\n  fragColor = vec4(col, 1.0);\n}\n","smoke":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// Smoke: large-scale fBm, slow rise, soft contrast.\n\nfloat hash12(vec2 p) {\n  vec3 p3 = fract(vec3(p.xyx) * 0.1031);\n  p3 += dot(p3, p3.yzx + 33.33);\n  return fract((p3.x + p3.y) * p3.z);\n}\nfloat noise(vec2 p) {\n  vec2 i = floor(p), f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1,0)), u.x),\n             mix(hash12(i + vec2(0,1)), hash12(i + vec2(1,1)), u.x), u.y);\n}\nfloat fbm(vec2 p) {\n  float v = 0.0, a = 0.5;\n  mat2 m = mat2(1.6, 1.2, -1.2, 1.6);\n  for (int i = 0; i < 6; i++) { v += a * noise(p); p = m * p; a *= 0.52; }\n  return v;\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;\n  vec2 q = vec2(fbm(p * 1.4 + iTime * 0.05), fbm(p * 1.4 + 5.1));\n  float n = fbm(p * 2.0 + 3.0 * q + vec2(0.0, -iTime * 0.12));\n  float dens = smoothstep(0.35, 0.85, n);\n  dens *= smoothstep(1.1, 0.1, length(p * vec2(0.7, 0.9)));\n  vec3 bg = vec3(0.06, 0.07, 0.09);\n  vec3 sm = mix(vec3(0.15, 0.16, 0.18), vec3(0.45, 0.48, 0.52), dens);\n  vec3 col = mix(bg, sm, dens);\n  fragColor = vec4(col, 1.0);\n}\n","steam":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// Steam / hot vent: white wisps rising from a grate.\n\nfloat hash12(vec2 p) {\n  vec3 p3 = fract(vec3(p.xyx) * 0.1031);\n  p3 += dot(p3, p3.yzx + 33.33);\n  return fract((p3.x + p3.y) * p3.z);\n}\nfloat noise(vec2 p) {\n  vec2 i = floor(p), f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1,0)), u.x),\n             mix(hash12(i + vec2(0,1)), hash12(i + vec2(1,1)), u.x), u.y);\n}\nfloat fbm(vec2 p) {\n  float v = 0.0, a = 0.5;\n  for (int i = 0; i < 5; i++) { v += a * noise(p); p *= 2.05; a *= 0.5; }\n  return v;\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;\n  vec3 col = vec3(0.08, 0.08, 0.09);\n  float grate = step(0.0, sin(p.x * 70.0)) * smoothstep(-0.42, -0.38, p.y) * smoothstep(-0.48, -0.42, -p.y);\n  grate *= smoothstep(0.28, 0.22, abs(p.x));\n  col = mix(col, vec3(0.18), grate);\n\n  vec2 q = vec2(p.x * 2.5, p.y * 2.0 - iTime * 0.35);\n  q.x += 0.4 * fbm(q + iTime * 0.1);\n  float s = fbm(q);\n  float mask = exp(-6.0 * p.x * p.x) * smoothstep(-0.45, 0.1, p.y) * smoothstep(0.7, 0.0, p.y);\n  float steam = smoothstep(0.4, 0.75, s) * mask;\n  col = mix(col, vec3(0.75, 0.78, 0.8), steam);\n  fragColor = vec4(col, 1.0);\n}\n","sparks":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// Sparks / embers rising from the bottom.\n\nfloat hash12(vec2 p) {\n  vec3 p3 = fract(vec3(p.xyx) * 0.1031);\n  p3 += dot(p3, p3.yzx + 33.33);\n  return fract((p3.x + p3.y) * p3.z);\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;\n  vec3 col = vec3(0.03, 0.02, 0.02);\n  for (int i = 0; i < 40; i++) {\n    float fi = float(i);\n    float rnd = hash12(vec2(fi, 3.1));\n    float t = fract(iTime * (0.15 + rnd * 0.25) + rnd);\n    float x = (hash12(vec2(fi, 8.8)) - 0.5) * 1.2 + 0.08 * sin(iTime * 2.0 + fi);\n    float y = mix(-0.55, 0.7, t);\n    float size = 0.006 + 0.01 * (1.0 - t);\n    float d = length(p - vec2(x, y));\n    float spark = exp(-d * d / (size * size));\n    vec3 c = mix(vec3(1.0, 0.3, 0.05), vec3(1.0, 0.9, 0.4), rnd);\n    col += c * spark * (1.0 - t);\n  }\n  fragColor = vec4(col, 1.0);\n}\n","waterfall":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// Waterfall: cliff SDF, falling sheet, pool, mist.\n\nfloat hash12(vec2 p) {\n  vec3 p3 = fract(vec3(p.xyx) * 0.1031);\n  p3 += dot(p3, p3.yzx + 33.33);\n  return fract((p3.x + p3.y) * p3.z);\n}\nfloat noise(vec2 p) {\n  vec2 i = floor(p), f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1,0)), u.x),\n             mix(hash12(i + vec2(0,1)), hash12(i + vec2(1,1)), u.x), u.y);\n}\nfloat fbm(vec2 p) {\n  float v = 0.0, a = 0.5;\n  mat2 m = mat2(1.6, 1.2, -1.2, 1.6);\n  for (int i = 0; i < 5; i++) { v += a * noise(p); p = m * p; a *= 0.5; }\n  return v;\n}\nfloat sdBox(vec2 p, vec2 b) {\n  vec2 d = abs(p) - b;\n  return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0);\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;\n  vec3 sky = mix(vec3(0.45, 0.62, 0.78), vec3(0.72, 0.84, 0.92), p.y * 0.5 + 0.5);\n  vec3 col = sky;\n\n  float cliffL = sdBox(p - vec2(-0.62, 0.05), vec2(0.28, 0.7));\n  float cliffR = sdBox(p - vec2(0.64, -0.05), vec2(0.22, 0.75));\n  float rock = min(cliffL, cliffR);\n  rock += 0.04 * fbm(p * 6.0);\n  vec3 rockCol = mix(vec3(0.22, 0.20, 0.18), vec3(0.38, 0.34, 0.28), fbm(p * 8.0));\n  col = mix(col, rockCol, 1.0 - smoothstep(0.0, 0.01, rock));\n\n  float sheet = abs(p.x + 0.04 * sin(p.y * 8.0 + iTime)) - 0.16;\n  sheet = 1.0 - smoothstep(0.0, 0.04, sheet);\n  sheet *= smoothstep(-0.55, -0.15, p.y) * smoothstep(0.85, 0.35, p.y);\n  vec2 flow = vec2(p.x * 6.0, p.y * 10.0 + iTime * 4.5);\n  float streaks = fbm(flow);\n  vec3 water = mix(vec3(0.25, 0.45, 0.55), vec3(0.75, 0.88, 0.95), streaks);\n  col = mix(col, water, sheet * 0.9);\n\n  float poolY = -0.42;\n  float pool = smoothstep(0.02, -0.08, p.y - poolY) * smoothstep(0.7, 0.15, abs(p.x));\n  vec2 pu = vec2(p.x * 4.0 + iTime * 0.3, p.y * 8.0);\n  vec3 poolC = mix(vec3(0.12, 0.28, 0.35), vec3(0.45, 0.7, 0.75), fbm(pu));\n  col = mix(col, poolC, pool * 0.85);\n\n  float foam = sheet * smoothstep(-0.25, -0.42, p.y) * (0.5 + 0.5 * fbm(p * 20.0 + iTime * 3.0));\n  foam += pool * exp(-18.0 * abs(p.x)) * smoothstep(-0.35, -0.42, p.y);\n  col = mix(col, vec3(0.92, 0.95, 0.98), clamp(foam, 0.0, 1.0));\n\n  float mist = fbm(p * 3.0 + vec2(0.0, -iTime * 0.2)) * smoothstep(-0.1, -0.5, p.y);\n  col = mix(col, vec3(0.8, 0.85, 0.9), mist * 0.35);\n  fragColor = vec4(col, 1.0);\n}\n","water":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// Top-down pond: layered sines, sparkle, dark depth.\n\nfloat hash12(vec2 p) {\n  vec3 p3 = fract(vec3(p.xyx) * 0.1031);\n  p3 += dot(p3, p3.yzx + 33.33);\n  return fract((p3.x + p3.y) * p3.z);\n}\nfloat noise(vec2 p) {\n  vec2 i = floor(p), f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1,0)), u.x),\n             mix(hash12(i + vec2(0,1)), hash12(i + vec2(1,1)), u.x), u.y);\n}\nfloat fbm(vec2 p) {\n  float v = 0.0, a = 0.5;\n  mat2 m = mat2(1.6, 1.2, -1.2, 1.6);\n  for (int i = 0; i < 5; i++) { v += a * noise(p); p = m * p; a *= 0.5; }\n  return v;\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;\n  float h = 0.0;\n  h += 0.045 * sin(dot(p, vec2(8.0, 2.0)) + iTime * 1.6);\n  h += 0.03 * sin(dot(p, vec2(-3.0, 9.0)) + iTime * 2.1);\n  h += 0.02 * fbm(p * 6.0 + iTime * 0.25);\n  vec2 e = vec2(0.01, 0.0);\n  float hx = (0.045 * sin(dot(p + e.xy, vec2(8.0, 2.0)) + iTime * 1.6)) - h;\n  float hy = (0.045 * sin(dot(p + e.yx, vec2(8.0, 2.0)) + iTime * 1.6)) - h;\n  vec3 N = normalize(vec3(-hx, 0.12, -hy));\n  vec3 L = normalize(vec3(0.4, 0.8, 0.3));\n  float nd = max(dot(N, L), 0.0);\n  float spec = pow(max(dot(N, normalize(L + vec3(0.0, 1.0, 0.0))), 0.0), 80.0);\n  vec3 deep = vec3(0.02, 0.12, 0.18);\n  vec3 shallow = vec3(0.12, 0.45, 0.48);\n  float depth = 0.45 + 0.55 * fbm(p * 2.0);\n  vec3 col = mix(deep, shallow, depth) * (0.35 + 0.65 * nd);\n  col += vec3(0.85, 0.95, 1.0) * spec * 0.7;\n  float spark = smoothstep(0.82, 0.95, fbm(p * 18.0 + iTime));\n  col += spark * 0.25;\n  fragColor = vec4(pow(col, vec3(0.9)), 1.0);\n}\n","ocean":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// Ocean: ray-marched plane, summed sines, sky, sun spec.\n\nfloat hash12(vec2 p) {\n  vec3 p3 = fract(vec3(p.xyx) * 0.1031);\n  p3 += dot(p3, p3.yzx + 33.33);\n  return fract((p3.x + p3.y) * p3.z);\n}\nfloat noise(vec2 p) {\n  vec2 i = floor(p), f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1,0)), u.x),\n             mix(hash12(i + vec2(0,1)), hash12(i + vec2(1,1)), u.x), u.y);\n}\n\nfloat wave(vec2 xz) {\n  float h = 0.0;\n  h += 0.22 * sin(dot(xz, vec2(0.8, 0.3)) * 1.3 + iTime * 1.1);\n  h += 0.12 * sin(dot(xz, vec2(-0.6, 0.9)) * 2.1 + iTime * 1.7);\n  h += 0.06 * sin(dot(xz, vec2(0.2, -1.0)) * 3.4 + iTime * 2.3);\n  h += 0.04 * noise(xz * 2.5 + iTime * 0.4);\n  return h;\n}\n\nvec3 sky(vec3 rd) {\n  vec3 z = vec3(0.25, 0.45, 0.75);\n  vec3 h = vec3(0.75, 0.62, 0.5);\n  vec3 s = mix(h, z, pow(max(rd.y, 0.0), 0.45));\n  vec3 sun = normalize(vec3(0.45, 0.28, 0.6));\n  s += vec3(1.0, 0.85, 0.5) * pow(max(dot(rd, sun), 0.0), 256.0);\n  s += vec3(1.0, 0.55, 0.25) * pow(max(dot(rd, sun), 0.0), 6.0) * 0.25;\n  return s;\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;\n  vec3 ro = vec3(0.0, 1.6, iTime * 0.4);\n  vec3 rd = normalize(vec3(uv.x, uv.y - 0.15, 1.4));\n  float t = (0.0 - ro.y) / rd.y;\n  vec3 col;\n  if (t > 0.0 && rd.y < 0.0) {\n    vec3 pos = ro + rd * t;\n    float e = 0.08;\n    float hx = wave(pos.xz + vec2(e, 0.0)) - wave(pos.xz - vec2(e, 0.0));\n    float hz = wave(pos.xz + vec2(0.0, e)) - wave(pos.xz - vec2(0.0, e));\n    vec3 N = normalize(vec3(-hx, 2.0 * e, -hz));\n    vec3 R = reflect(rd, N);\n    vec3 water = mix(vec3(0.02, 0.08, 0.12), sky(R), 0.55 + 0.45 * pow(1.0 - max(dot(N, -rd), 0.0), 3.0));\n    vec3 L = normalize(vec3(0.45, 0.55, 0.6));\n    water += vec3(1.0, 0.9, 0.6) * pow(max(dot(N, L), 0.0), 80.0);\n    float fog = exp(-0.012 * t);\n    col = mix(sky(rd), water, fog);\n  } else {\n    col = sky(rd);\n  }\n  fragColor = vec4(pow(col, vec3(0.92)), 1.0);\n}\n","river":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// River: banks, current, foam around rock islands.\n\nfloat hash12(vec2 p) {\n  vec3 p3 = fract(vec3(p.xyx) * 0.1031);\n  p3 += dot(p3, p3.yzx + 33.33);\n  return fract((p3.x + p3.y) * p3.z);\n}\nfloat noise(vec2 p) {\n  vec2 i = floor(p), f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1,0)), u.x),\n             mix(hash12(i + vec2(0,1)), hash12(i + vec2(1,1)), u.x), u.y);\n}\nfloat fbm(vec2 p) {\n  float v = 0.0, a = 0.5;\n  mat2 m = mat2(1.6, 1.2, -1.2, 1.6);\n  for (int i = 0; i < 5; i++) { v += a * noise(p); p = m * p; a *= 0.5; }\n  return v;\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;\n  float bank = 0.38 + 0.06 * sin(p.y * 3.0) + 0.04 * fbm(vec2(p.y * 2.0, 0.0));\n  float river = 1.0 - smoothstep(bank - 0.02, bank + 0.02, abs(p.x));\n  vec3 grass = mix(vec3(0.18, 0.28, 0.12), vec3(0.32, 0.42, 0.16), fbm(p * 8.0));\n  vec2 flow = vec2(p.x * 5.0, p.y * 4.0 - iTime * 1.4);\n  float n = fbm(flow);\n  vec3 water = mix(vec3(0.08, 0.22, 0.28), vec3(0.25, 0.5, 0.52), n);\n  vec3 col = mix(grass, water, river);\n\n  vec2 r1 = p - vec2(-0.05, 0.15);\n  vec2 r2 = p - vec2(0.12, -0.25);\n  float rock = min(length(r1) - 0.07, length(r2) - 0.05);\n  col = mix(col, vec3(0.25, 0.22, 0.2), 1.0 - smoothstep(0.0, 0.01, rock));\n  float foam = river * (1.0 - smoothstep(0.02, 0.12, rock)) * (0.4 + 0.6 * fbm(p * 16.0 + iTime));\n  foam += river * smoothstep(bank - 0.04, bank, abs(p.x)) * 0.45;\n  col = mix(col, vec3(0.9, 0.93, 0.95), clamp(foam, 0.0, 1.0));\n  fragColor = vec4(col, 1.0);\n}\n","fountain":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// Fountain: basin, vertical jet, falling spray.\n\nfloat hash12(vec2 p) {\n  vec3 p3 = fract(vec3(p.xyx) * 0.1031);\n  p3 += dot(p3, p3.yzx + 33.33);\n  return fract((p3.x + p3.y) * p3.z);\n}\nfloat noise(vec2 p) {\n  vec2 i = floor(p), f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1,0)), u.x),\n             mix(hash12(i + vec2(0,1)), hash12(i + vec2(1,1)), u.x), u.y);\n}\nfloat fbm(vec2 p) {\n  float v = 0.0, a = 0.5;\n  for (int i = 0; i < 4; i++) { v += a * noise(p); p *= 2.02; a *= 0.5; }\n  return v;\n}\nfloat sdCircle(vec2 p, float r) { return length(p) - r; }\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;\n  vec3 col = mix(vec3(0.15, 0.18, 0.22), vec3(0.45, 0.55, 0.6), p.y * 0.5 + 0.5);\n\n  float basin = sdCircle(p - vec2(0.0, -0.38), 0.32);\n  col = mix(col, vec3(0.35, 0.32, 0.28), 1.0 - smoothstep(0.0, 0.01, abs(basin) - 0.02) * step(basin, 0.03));\n  float water = 1.0 - smoothstep(0.0, 0.01, sdCircle(p - vec2(0.0, -0.38), 0.26));\n  col = mix(col, vec3(0.15, 0.35, 0.42), water * 0.8);\n\n  float jet = abs(p.x) - 0.018 - 0.01 * sin(p.y * 30.0 + iTime * 12.0);\n  jet = 1.0 - smoothstep(0.0, 0.012, jet);\n  jet *= smoothstep(-0.35, -0.1, p.y) * smoothstep(0.42, 0.15, p.y);\n  vec3 jetC = mix(vec3(0.4, 0.65, 0.75), vec3(0.9, 0.95, 1.0), fbm(vec2(p.x * 20.0, p.y * 12.0 - iTime * 6.0)));\n  col = mix(col, jetC, jet);\n\n  float spray = 0.0;\n  for (int i = 0; i < 12; i++) {\n    float fi = float(i);\n    float ph = fract(iTime * 0.55 + fi * 0.08);\n    float x = (hash12(vec2(fi, 1.0)) - 0.5) * 0.55 * ph;\n    float y = 0.28 - 1.1 * ph * ph;\n    spray += smoothstep(0.03, 0.0, length(p - vec2(x, y)));\n  }\n  col = mix(col, vec3(0.85, 0.92, 0.98), clamp(spray, 0.0, 1.0));\n  fragColor = vec4(col, 1.0);\n}\n","rain":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// Rain: streaks in view, wet dark ground, occasional splash rings.\n\nfloat hash12(vec2 p) {\n  vec3 p3 = fract(vec3(p.xyx) * 0.1031);\n  p3 += dot(p3, p3.yzx + 33.33);\n  return fract((p3.x + p3.y) * p3.z);\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 uv = fragCoord / iResolution.xy;\n  vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;\n  vec3 col = mix(vec3(0.08, 0.09, 0.11), vec3(0.16, 0.18, 0.2), uv.y);\n\n  float ground = smoothstep(0.02, -0.05, p.y + 0.25);\n  col = mix(col, vec3(0.05, 0.06, 0.07), ground);\n  float sheen = pow(max(0.0, 1.0 - abs(p.x * 0.4 + 0.2)), 8.0) * ground;\n  col += vec3(0.12, 0.14, 0.16) * sheen;\n\n  for (int i = 0; i < 3; i++) {\n    float fi = float(i);\n    vec2 q = uv * vec2(40.0 + fi * 12.0, 12.0 + fi * 4.0);\n    q.y += iTime * (6.0 + fi * 2.0);\n    vec2 id = floor(q);\n    vec2 f = fract(q);\n    float rnd = hash12(id + fi * 13.1);\n    if (rnd > 0.35) {\n      float streak = smoothstep(0.08, 0.0, abs(f.x - 0.5)) * smoothstep(0.0, 0.4, f.y) * (1.0 - ground);\n      col += vec3(0.55, 0.6, 0.65) * streak * 0.25;\n    }\n  }\n\n  vec2 sp = p - vec2(-0.15, -0.28);\n  float ring = abs(length(sp) - fract(iTime * 0.7 + hash12(floor(sp * 3.0))) * 0.12);\n  col += vec3(0.4) * (1.0 - smoothstep(0.0, 0.008, ring)) * ground * 0.5;\n  fragColor = vec4(col, 1.0);\n}\n","foam":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// Shore foam: voronoi cells + moving band.\n\nfloat hash12(vec2 p) {\n  vec3 p3 = fract(vec3(p.xyx) * 0.1031);\n  p3 += dot(p3, p3.yzx + 33.33);\n  return fract((p3.x + p3.y) * p3.z);\n}\nvec2 hash22(vec2 p) {\n  vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973));\n  p3 += dot(p3, p3.yzx + 33.33);\n  return fract((p3.xx + p3.yz) * p3.zy);\n}\nfloat noise(vec2 p) {\n  vec2 i = floor(p), f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1,0)), u.x),\n             mix(hash12(i + vec2(0,1)), hash12(i + vec2(1,1)), u.x), u.y);\n}\n\nfloat voro(vec2 p) {\n  vec2 n = floor(p), f = fract(p);\n  float md = 8.0;\n  for (int j = -1; j <= 1; j++)\n  for (int i = -1; i <= 1; i++) {\n    vec2 g = vec2(float(i), float(j));\n    vec2 o = hash22(n + g);\n    md = min(md, length(g + o - f));\n  }\n  return md;\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 uv = fragCoord / iResolution.xy;\n  vec2 p = uv * vec2(iResolution.x / iResolution.y, 1.0);\n  float shore = uv.y + 0.04 * sin(uv.x * 12.0 + iTime) + 0.03 * noise(p * 4.0 + iTime * 0.2);\n  vec3 sea = mix(vec3(0.05, 0.2, 0.28), vec3(0.15, 0.4, 0.42), uv.y);\n  vec3 sand = vec3(0.55, 0.48, 0.35);\n  vec3 col = mix(sea, sand, smoothstep(0.42, 0.48, shore));\n  float band = smoothstep(0.36, 0.44, shore) * smoothstep(0.52, 0.44, shore);\n  float cells = 1.0 - smoothstep(0.15, 0.45, voro(p * 18.0 + vec2(iTime * 0.4, 0.0)));\n  col = mix(col, vec3(0.92, 0.95, 0.97), band * cells);\n  fragColor = vec4(col, 1.0);\n}\n","caustics":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// Caustics: interfering sines, typical pool-floor look.\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 uv = fragCoord / iResolution.xy;\n  vec2 p = uv * vec2(iResolution.x / iResolution.y, 1.0) * 6.0;\n  float t = iTime * 0.7;\n  float a = sin(p.x + t) + sin(p.y * 1.3 + t * 1.1);\n  float b = sin(p.x * 1.2 - p.y + t * 0.8) + sin(dot(p, vec2(0.7, 1.1)) + t);\n  float c = sin(length(p) - t * 1.4);\n  float k = a * b * 0.35 + c * 0.25;\n  float cau = pow(0.5 + 0.5 * k, 3.0);\n  vec3 floorC = mix(vec3(0.05, 0.18, 0.22), vec3(0.15, 0.45, 0.4), uv.y);\n  vec3 col = floorC + vec3(0.4, 0.85, 0.9) * cau * 0.85;\n  fragColor = vec4(col, 1.0);\n}\n","ripples":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// Ripples: click/drag (iMouse) to drop rings. Also idle rain drops.\n\nfloat hash12(vec2 p) {\n  vec3 p3 = fract(vec3(p.xyx) * 0.1031);\n  p3 += dot(p3, p3.yzx + 33.33);\n  return fract((p3.x + p3.y) * p3.z);\n}\n\nfloat ring(vec2 p, vec2 c, float t, float life) {\n  float d = length(p - c);\n  float r = t * 0.45;\n  float w = 0.012 + 0.01 * t;\n  float wave = exp(-3.0 * t) * sin((d - r) * 40.0);\n  return wave * smoothstep(w, 0.0, abs(d - r)) * step(t, life);\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;\n  vec3 col = mix(vec3(0.05, 0.12, 0.16), vec3(0.1, 0.28, 0.32), 0.5 + 0.5 * p.y);\n  float h = 0.0;\n  for (int i = 0; i < 8; i++) {\n    float fi = float(i);\n    float rnd = hash12(vec2(fi, 2.7));\n    float t = mod(iTime * 0.6 + rnd * 5.0, 4.0);\n    vec2 c = vec2(rnd * 1.6 - 0.8, hash12(vec2(fi, 9.1)) * 1.0 - 0.5);\n    h += ring(p, c, t, 3.5);\n  }\n  if (iMouse.z > 0.0) {\n    vec2 m = (iMouse.xy - 0.5 * iResolution.xy) / iResolution.y;\n    h += ring(p, m, 0.15, 2.0) * 2.0;\n  }\n  vec3 N = normalize(vec3(-dFdx(h), 0.15, -dFdy(h)));\n  float spec = pow(max(N.y, 0.0), 20.0);\n  col += vec3(0.7, 0.9, 1.0) * h * 0.35 + spec * 0.15;\n  fragColor = vec4(col, 1.0);\n}\n","underwater":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// Underwater: murk, godrays, caustic floor.\n\nfloat hash12(vec2 p) {\n  vec3 p3 = fract(vec3(p.xyx) * 0.1031);\n  p3 += dot(p3, p3.yzx + 33.33);\n  return fract((p3.x + p3.y) * p3.z);\n}\nfloat noise(vec2 p) {\n  vec2 i = floor(p), f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1,0)), u.x),\n             mix(hash12(i + vec2(0,1)), hash12(i + vec2(1,1)), u.x), u.y);\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 uv = fragCoord / iResolution.xy;\n  vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;\n  vec3 deep = vec3(0.0, 0.05, 0.08);\n  vec3 mid = vec3(0.02, 0.18, 0.22);\n  vec3 col = mix(deep, mid, uv.y);\n\n  float floorY = -0.35;\n  float floorM = smoothstep(0.02, -0.08, p.y - floorY);\n  vec2 fp = vec2(p.x * 4.0, iTime * 0.3);\n  float cau = pow(0.5 + 0.5 * sin(fp.x + iTime) * sin(fp.x * 1.3 - iTime * 0.7), 3.0);\n  vec3 sand = vec3(0.15, 0.22, 0.18) + vec3(0.3, 0.7, 0.7) * cau * 0.5;\n  col = mix(col, sand, floorM);\n\n  float rays = 0.0;\n  for (int i = 0; i < 5; i++) {\n    float fi = float(i);\n    float x = sin(iTime * 0.2 + fi) * 0.15 + fi * 0.12 - 0.4;\n    rays += smoothstep(0.06, 0.0, abs(p.x - x - p.y * 0.15)) * (0.15 + 0.1 * noise(vec2(p.y * 3.0, fi)));\n  }\n  col += vec3(0.25, 0.45, 0.4) * rays * (0.4 + 0.6 * uv.y);\n\n  float bits = smoothstep(0.92, 1.0, noise(p * 40.0 + iTime));\n  col += bits * 0.08;\n  col *= 0.85 + 0.15 * uv.y;\n  fragColor = vec4(col, 1.0);\n}\n","clouds":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// Clouds: fBm density, sky gradient, sun rim.\n\nfloat hash12(vec2 p) {\n  vec3 p3 = fract(vec3(p.xyx) * 0.1031);\n  p3 += dot(p3, p3.yzx + 33.33);\n  return fract((p3.x + p3.y) * p3.z);\n}\nfloat noise(vec2 p) {\n  vec2 i = floor(p), f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1,0)), u.x),\n             mix(hash12(i + vec2(0,1)), hash12(i + vec2(1,1)), u.x), u.y);\n}\nfloat fbm(vec2 p) {\n  float v = 0.0, a = 0.5;\n  mat2 m = mat2(1.6, 1.2, -1.2, 1.6);\n  for (int i = 0; i < 6; i++) { v += a * noise(p); p = m * p; a *= 0.5; }\n  return v;\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;\n  vec3 sky = mix(vec3(0.55, 0.7, 0.9), vec3(0.2, 0.4, 0.75), p.y * 0.5 + 0.3);\n  vec2 q = vec2(fbm(p * 1.5 + iTime * 0.03), fbm(p * 1.5 + 4.0));\n  float c = fbm(p * 2.2 + 2.5 * q + vec2(iTime * 0.04, 0.0));\n  c = smoothstep(0.45, 0.78, c);\n  c *= smoothstep(-0.85, -0.1, p.y);\n  vec3 cloud = mix(vec3(0.75, 0.8, 0.88), vec3(1.0), c);\n  float rim = pow(c, 3.0) * (0.5 + 0.5 * p.x);\n  cloud += vec3(1.0, 0.9, 0.7) * rim * 0.2;\n  vec3 col = mix(sky, cloud, c);\n  fragColor = vec4(col, 1.0);\n}\n","mist":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// Ground mist + dark tree cards.\n\nfloat hash12(vec2 p) {\n  vec3 p3 = fract(vec3(p.xyx) * 0.1031);\n  p3 += dot(p3, p3.yzx + 33.33);\n  return fract((p3.x + p3.y) * p3.z);\n}\nfloat noise(vec2 p) {\n  vec2 i = floor(p), f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1,0)), u.x),\n             mix(hash12(i + vec2(0,1)), hash12(i + vec2(1,1)), u.x), u.y);\n}\nfloat fbm(vec2 p) {\n  float v = 0.0, a = 0.5;\n  for (int i = 0; i < 5; i++) { v += a * noise(p); p *= 2.02; a *= 0.5; }\n  return v;\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;\n  vec3 col = mix(vec3(0.35, 0.4, 0.42), vec3(0.55, 0.6, 0.65), p.y + 0.4);\n  for (int i = 0; i < 5; i++) {\n    float fi = float(i);\n    float x = -0.7 + fi * 0.32 + 0.05 * sin(fi);\n    float trunk = smoothstep(0.012, 0.0, abs(p.x - x)) * smoothstep(-0.45, -0.1, p.y);\n    float crown = smoothstep(0.22, 0.0, length(p - vec2(x, 0.12)) - 0.02 * fbm(p * 8.0));\n    col = mix(col, vec3(0.08, 0.09, 0.08), max(trunk, crown) * 0.85);\n  }\n  float mist = fbm(vec2(p.x * 1.5 + iTime * 0.05, p.y * 2.0));\n  mist *= smoothstep(0.25, -0.5, p.y);\n  col = mix(col, vec3(0.75, 0.78, 0.8), mist * 0.65);\n  fragColor = vec4(col, 1.0);\n}\n","snow":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// Snow: several parallax flake layers.\n\nfloat hash12(vec2 p) {\n  vec3 p3 = fract(vec3(p.xyx) * 0.1031);\n  p3 += dot(p3, p3.yzx + 33.33);\n  return fract((p3.x + p3.y) * p3.z);\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 uv = fragCoord / iResolution.xy;\n  vec3 col = mix(vec3(0.15, 0.18, 0.22), vec3(0.45, 0.5, 0.55), uv.y);\n  col = mix(col, vec3(0.7, 0.74, 0.78), smoothstep(0.15, 0.0, uv.y));\n  for (int L = 0; L < 3; L++) {\n    float fl = float(L);\n    float scale = 12.0 + fl * 18.0;\n    vec2 q = uv * scale;\n    q.y += iTime * (0.25 + fl * 0.2);\n    q.x += iTime * 0.08 * (fl + 1.0);\n    vec2 id = floor(q);\n    vec2 f = fract(q) - 0.5;\n    float rnd = hash12(id + fl * 7.3);\n    f += (rnd - 0.5) * 0.4;\n    float r = 0.015 + 0.02 * hash12(id + 2.2);\n    float flake = smoothstep(r, 0.0, length(f));\n    col += flake * (0.35 + 0.25 * fl);\n  }\n  fragColor = vec4(col, 1.0);\n}\n","aurora":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// Aurora: vertical curtains, slow phase drift.\n\nfloat hash12(vec2 p) {\n  vec3 p3 = fract(vec3(p.xyx) * 0.1031);\n  p3 += dot(p3, p3.yzx + 33.33);\n  return fract((p3.x + p3.y) * p3.z);\n}\nfloat noise(vec2 p) {\n  vec2 i = floor(p), f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1,0)), u.x),\n             mix(hash12(i + vec2(0,1)), hash12(i + vec2(1,1)), u.x), u.y);\n}\nfloat fbm(vec2 p) {\n  float v = 0.0, a = 0.5;\n  for (int i = 0; i < 5; i++) { v += a * noise(p); p *= 2.03; a *= 0.5; }\n  return v;\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;\n  vec3 col = mix(vec3(0.01, 0.02, 0.06), vec3(0.0, 0.0, 0.02), p.y * 0.5 + 0.5);\n  float y = p.y + 0.15;\n  float curtain = fbm(vec2(p.x * 1.4 + iTime * 0.08, 0.3));\n  float band = exp(-3.5 * abs(y - 0.15 - 0.25 * curtain));\n  float detail = fbm(vec2(p.x * 3.0 - iTime * 0.12, y * 2.0));\n  vec3 g = vec3(0.1, 0.85, 0.45);\n  vec3 ppl = vec3(0.55, 0.15, 0.75);\n  vec3 aur = mix(g, ppl, clamp(p.x * 0.5 + 0.5 + 0.2 * detail, 0.0, 1.0));\n  col += aur * band * (0.35 + 0.65 * detail) * smoothstep(-0.6, 0.1, y);\n  float stars = step(0.992, hash12(floor(fragCoord.xy)));\n  col += stars * 0.7;\n  fragColor = vec4(col, 1.0);\n}\n","lightning":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// Lightning: branching bolt. Can strobe — warn the room.\n\nfloat hash12(vec2 p) {\n  vec3 p3 = fract(vec3(p.xyx) * 0.1031);\n  p3 += dot(p3, p3.yzx + 33.33);\n  return fract((p3.x + p3.y) * p3.z);\n}\nfloat noise(vec2 p) {\n  vec2 i = floor(p), f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1,0)), u.x),\n             mix(hash12(i + vec2(0,1)), hash12(i + vec2(1,1)), u.x), u.y);\n}\n\nfloat bolt(vec2 p, vec2 a, vec2 b, float seed) {\n  vec2 pa = p - a, ba = b - a;\n  float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);\n  vec2 n = normalize(vec2(-ba.y, ba.x));\n  float off = (noise(vec2(h * 8.0, seed + iTime * 20.0)) - 0.5) * 0.18;\n  return length(pa - ba * h - n * off);\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;\n  vec3 col = vec3(0.02, 0.03, 0.06);\n  float flash = step(0.92, fract(sin(floor(iTime * 2.4)) * 43758.5));\n  flash = max(flash, step(0.0, iMouse.z));\n  vec2 a = vec2(-0.05, 0.55);\n  vec2 b = vec2(0.08, -0.45);\n  float d = bolt(p, a, b, 1.0);\n  d = min(d, bolt(p, mix(a, b, 0.45), vec2(0.35, -0.05), 2.2));\n  d = min(d, bolt(p, mix(a, b, 0.6), vec2(-0.32, -0.2), 3.1));\n  float core = 1.0 - smoothstep(0.0, 0.012, d);\n  float glow = 1.0 - smoothstep(0.0, 0.08, d);\n  col += (vec3(0.6, 0.75, 1.0) * glow * 0.45 + vec3(1.0) * core) * (0.15 + 0.85 * flash);\n  col += vec3(0.15, 0.18, 0.25) * flash * 0.25;\n  fragColor = vec4(col, 1.0);\n}\n","plasma":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// Classic sine plasma. Can flicker — warn the room.\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 uv = fragCoord / iResolution.xy;\n  vec2 p = uv * 2.0 - 1.0;\n  p.x *= iResolution.x / iResolution.y;\n  float t = iTime;\n  float v = 0.0;\n  v += sin(p.x * 4.0 + t);\n  v += sin(p.y * 5.0 + t * 1.3);\n  v += sin((p.x + p.y) * 3.0 + t * 0.7);\n  v += sin(length(p) * 6.0 - t * 1.5);\n  vec3 col = 0.5 + 0.5 * cos(vec3(0.0, 2.0, 4.0) + v + t * 0.4);\n  fragColor = vec4(col, 1.0);\n}\n","seascape":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// Seascape: height-field waves, fresnel sky, sun path. Drag to look.\n// Genre made famous on Shadertoy; this implementation is original.\n\nfloat hash12(vec2 p) {\n  vec3 p3 = fract(vec3(p.xyx) * 0.1031);\n  p3 += dot(p3, p3.yzx + 33.33);\n  return fract((p3.x + p3.y) * p3.z);\n}\nfloat noise(vec2 p) {\n  vec2 i = floor(p), f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1,0)), u.x),\n             mix(hash12(i + vec2(0,1)), hash12(i + vec2(1,1)), u.x), u.y);\n}\n\nfloat sea(vec2 xz) {\n  float h = 0.0, a = 0.42, f = 0.85;\n  vec2 d = normalize(vec2(1.0, 0.35));\n  for (int i = 0; i < 6; i++) {\n    float ph = iTime * (1.1 + 0.15 * float(i));\n    h += a * sin(dot(xz, d) * f + ph);\n    d = vec2(d.x * 0.72 - d.y * 0.69, d.x * 0.69 + d.y * 0.72);\n    a *= 0.52;\n    f *= 1.85;\n  }\n  h += 0.05 * noise(xz * 3.2 + iTime * 0.35);\n  return h;\n}\n\nvec3 sky(vec3 rd, vec3 sun) {\n  float h = max(rd.y, 0.0);\n  vec3 c = mix(vec3(0.72, 0.55, 0.38), vec3(0.18, 0.38, 0.72), pow(h, 0.45));\n  c += vec3(1.0, 0.85, 0.45) * pow(max(dot(rd, sun), 0.0), 220.0);\n  c += vec3(1.0, 0.5, 0.2) * pow(max(dot(rd, sun), 0.0), 5.0) * 0.28;\n  return c;\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;\n  float yaw = (iMouse.z > 0.0) ? (iMouse.x / iResolution.x - 0.5) * 1.6 : 0.18;\n  float pit = (iMouse.z > 0.0) ? (0.5 - iMouse.y / iResolution.y) * 0.5 : 0.12;\n  vec3 ro = vec3(0.0, 1.35, iTime * 0.55);\n  vec3 fwd = normalize(vec3(sin(yaw), -0.18 - pit, cos(yaw)));\n  vec3 right = normalize(cross(fwd, vec3(0, 1, 0)));\n  vec3 up = cross(right, fwd);\n  vec3 rd = normalize(fwd + uv.x * right + uv.y * up);\n  vec3 sun = normalize(vec3(0.55, 0.22, 0.65));\n\n  vec3 col;\n  if (rd.y < 0.0) {\n    float t = (0.0 - ro.y) / rd.y;\n    vec3 pos = ro + rd * t;\n    float e = 0.12;\n    vec3 N = normalize(vec3(\n      sea(pos.xz - vec2(e, 0.0)) - sea(pos.xz + vec2(e, 0.0)),\n      2.0 * e,\n      sea(pos.xz - vec2(0.0, e)) - sea(pos.xz + vec2(0.0, e))\n    ));\n    vec3 R = reflect(rd, N);\n    float fre = pow(1.0 - max(dot(N, -rd), 0.0), 4.0);\n    vec3 water = mix(vec3(0.01, 0.07, 0.12), sky(R, sun), 0.35 + 0.65 * fre);\n    water += vec3(1.0, 0.92, 0.7) * pow(max(dot(N, sun), 0.0), 90.0);\n    float foam = smoothstep(0.28, 0.55, sea(pos.xz * 0.35 + 12.0));\n    water = mix(water, vec3(0.85, 0.92, 0.95), foam * 0.18 * (1.0 - fre));\n    col = mix(sky(rd, sun), water, exp(-0.014 * t));\n  } else {\n    col = sky(rd, sun);\n  }\n  fragColor = vec4(pow(col, vec3(0.9)), 1.0);\n}\n","star-nest":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// Volumetric star field: walk a ray, fold/invert, accumulate glow.\n// Genre made famous on Shadertoy; this implementation is original.\n\nmat2 rot(float a) {\n  float c = cos(a), s = sin(a);\n  return mat2(c, -s, s, c);\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;\n  vec3 rd = normalize(vec3(uv, 1.25));\n  rd.xz = rot(iTime * 0.07) * rd.xz;\n  rd.xy = rot(0.28) * rd.xy;\n  vec3 p = vec3(0.4, 0.3, iTime * 0.18);\n  vec3 acc = vec3(0.0);\n  for (int i = 0; i < 22; i++) {\n    vec3 q = abs(fract(p * 0.08) * 2.0 - 1.0);\n    float m = 1.0;\n    for (int k = 0; k < 7; k++) {\n      q = abs(q);\n      q = q * (1.85 / clamp(dot(q, q), 0.12, 1.0)) - vec3(0.72, 0.64, 0.88);\n      m *= 1.12;\n    }\n    float d = length(q) / m;\n    vec3 glow = mix(vec3(0.45, 0.65, 1.25), vec3(1.15, 0.55, 0.28), fract(float(i) * 0.17));\n    acc += glow * (0.016 / (d + 0.015));\n    p += rd * (0.16 + d * 0.05);\n  }\n  acc = 1.0 - exp(-acc * 0.9);\n  fragColor = vec4(pow(acc, vec3(0.9)), 1.0);\n}\n","creation":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// RGB expanding rings / lattice glow. Can pulse — warn the room.\n// Genre made famous on Shadertoy; this implementation is original.\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;\n  vec3 col = vec3(0.0);\n  float t = iTime;\n  for (int i = 0; i < 3; i++) {\n    float fi = float(i);\n    float z = t * 0.85 + fi * 0.65;\n    vec2 q = p * (0.9 + 0.18 * sin(z + fi));\n    float ang = atan(q.y, q.x) + z * 0.35;\n    float r = length(q);\n    vec2 cell = vec2(ang / 6.2831853, r - 0.12 * sin(z * 1.5));\n    float d = length(fract(cell * vec2(7.0, 5.0)) - 0.5);\n    float glow = 0.016 / max(d, 0.0015);\n    col[i] = glow * (0.45 + 0.55 * sin(r * 9.0 - z * 2.2));\n  }\n  col *= 0.7 / (0.22 + length(p));\n  fragColor = vec4(col, 1.0);\n}\n","fractal-pyramid":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// Fractal pyramid: recursive box fold, glow along a ray.\n// Genre made famous on Shadertoy; this implementation is original.\n\nmat2 rot(float a) {\n  float c = cos(a), s = sin(a);\n  return mat2(c, -s, s, c);\n}\n\nfloat fold(vec3 p) {\n  float s = 1.0;\n  for (int i = 0; i < 6; i++) {\n    p = abs(p);\n    if (p.x < p.z) p.xz = p.zx;\n    if (p.y < p.z) p.yz = p.zy;\n    if (p.x < p.y) p.xy = p.yx;\n    p = p * 1.85 - vec3(0.55, 0.55, 0.85);\n    s *= 1.85;\n  }\n  return length(max(p, vec3(0.0))) / s;\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;\n  vec3 rd = normalize(vec3(uv, 1.35));\n  rd.yz = rot(0.45) * rd.yz;\n  rd.xz = rot(iTime * 0.15) * rd.xz;\n  vec3 ro = vec3(0.0, 0.15, -2.6);\n  vec3 acc = vec3(0.0);\n  float t = 0.0;\n  for (int i = 0; i < 70; i++) {\n    vec3 p = ro + rd * t;\n    float d = fold(p);\n    vec3 g = mix(vec3(0.25, 0.55, 1.1), vec3(1.0, 0.45, 0.85), fract(t * 0.35));\n    acc += g * (0.018 / (d + 0.008));\n    t += d * 0.55 + 0.012;\n    if (t > 8.0) break;\n  }\n  acc = 1.0 - exp(-acc * 0.55);\n  fragColor = vec4(pow(acc, vec3(0.9)), 1.0);\n}\n","primitives":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// SDF primitive gallery: sphere, box, torus, capsule, plane. Drag to orbit.\n\nfloat sdSphere(vec3 p, float r) { return length(p) - r; }\nfloat sdBox(vec3 p, vec3 b) {\n  vec3 q = abs(p) - b;\n  return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0);\n}\nfloat sdTorus(vec3 p, vec2 t) {\n  vec2 q = vec2(length(p.xz) - t.x, p.y);\n  return length(q) - t.y;\n}\nfloat sdCapsule(vec3 p, vec3 a, vec3 b, float r) {\n  vec3 pa = p - a, ba = b - a;\n  float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);\n  return length(pa - ba * h) - r;\n}\n\nvec2 map(vec3 p) {\n  float d = sdSphere(p - vec3(-1.15, 0.45, 0.0), 0.45);\n  float id = 1.0;\n  float box = sdBox(p - vec3(0.0, 0.4, 0.15), vec3(0.35, 0.4, 0.35));\n  if (box < d) { d = box; id = 2.0; }\n  float tor = sdTorus(p - vec3(1.2, 0.35, 0.0), vec2(0.38, 0.12));\n  if (tor < d) { d = tor; id = 3.0; }\n  float cap = sdCapsule(p, vec3(-0.35, 0.15, 1.05), vec3(0.35, 0.85, 1.05), 0.12);\n  if (cap < d) { d = cap; id = 4.0; }\n  float pl = p.y;\n  if (pl < d) { d = pl; id = 0.0; }\n  return vec2(d, id);\n}\n\nvec3 normal(vec3 p) {\n  vec2 e = vec2(0.0015, 0.0);\n  return normalize(vec3(\n    map(p + e.xyy).x - map(p - e.xyy).x,\n    map(p + e.yxy).x - map(p - e.yxy).x,\n    map(p + e.yyx).x - map(p - e.yyx).x\n  ));\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;\n  float ang = (iMouse.z > 0.0) ? (iMouse.x / iResolution.x) * 6.28318 : iTime * 0.25;\n  vec3 ro = vec3(3.2 * sin(ang), 1.55, 3.2 * cos(ang));\n  vec3 ta = vec3(0.0, 0.4, 0.2);\n  vec3 ww = normalize(ta - ro);\n  vec3 uu = normalize(cross(ww, vec3(0, 1, 0)));\n  vec3 vv = cross(uu, ww);\n  vec3 rd = normalize(uv.x * uu + uv.y * vv + 1.6 * ww);\n\n  float t = 0.0, id = -1.0;\n  for (int i = 0; i < 80; i++) {\n    vec2 h = map(ro + rd * t);\n    if (h.x < 0.001 || t > 18.0) { id = h.y; break; }\n    t += h.x;\n  }\n\n  vec3 sky = mix(vec3(0.55, 0.7, 0.9), vec3(0.15, 0.28, 0.5), uv.y * 0.5 + 0.5);\n  vec3 col = sky;\n  if (t < 18.0) {\n    vec3 p = ro + rd * t;\n    vec3 n = normal(p);\n    vec3 l = normalize(vec3(0.5, 0.8, 0.3));\n    float dif = max(dot(n, l), 0.0);\n    float amb = 0.22 + 0.18 * n.y;\n    float spec = pow(max(dot(n, normalize(l - rd)), 0.0), 48.0);\n    vec3 matc = vec3(0.55);\n    if (id < 0.5) matc = mix(vec3(0.22), vec3(0.32), step(0.0, sin(p.x * 4.0) * sin(p.z * 4.0)));\n    else if (id < 1.5) matc = vec3(0.85, 0.25, 0.2);\n    else if (id < 2.5) matc = vec3(0.25, 0.55, 0.9);\n    else if (id < 3.5) matc = vec3(0.95, 0.75, 0.2);\n    else matc = vec3(0.3, 0.8, 0.45);\n    col = matc * (amb + dif) + vec3(1.0) * spec * 0.35;\n    float sh = 1.0, st = 0.03;\n    for (int i = 0; i < 24; i++) {\n      float h = map(p + l * st).x;\n      sh = min(sh, 8.0 * h / st);\n      st += clamp(h, 0.02, 0.2);\n    }\n    col *= 0.35 + 0.65 * clamp(sh, 0.0, 1.0);\n  }\n  fragColor = vec4(pow(col, vec3(0.92)), 1.0);\n}\n","happy":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// Jumping SDF character: squash/stretch, eyes, ground contact. Original blob.\n\nfloat smin(float a, float b, float k) {\n  float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);\n  return mix(b, a, h) - k * h * (1.0 - h);\n}\n\nvec2 map(vec3 p) {\n  float jump = abs(sin(iTime * 3.2));\n  float squash = 1.0 - 0.28 * jump;\n  vec3 q = p;\n  q.y -= 0.28 + jump * 0.62;\n  q.y /= squash;\n  float body = length(q * vec3(1.0, 0.92, 1.05)) - 0.34;\n  vec3 hp = p - vec3(0.0, 0.52 + jump * 0.62, 0.0);\n  float head = length(hp) - 0.2;\n  float d = smin(body, head, 0.07);\n  float id = 1.0;\n  vec3 eyeL = hp - vec3(-0.07, 0.04, 0.16);\n  vec3 eyeR = hp - vec3(0.07, 0.04, 0.16);\n  float eyes = min(length(eyeL) - 0.045, length(eyeR) - 0.045);\n  if (eyes < d) { d = eyes; id = 3.0; }\n  float pupil = min(length(eyeL - vec3(0.0, 0.0, 0.02)) - 0.02,\n                    length(eyeR - vec3(0.0, 0.0, 0.02)) - 0.02);\n  if (pupil < d) { d = pupil; id = 4.0; }\n  float ground = p.y + 0.42;\n  if (ground < d) { d = ground; id = 2.0; }\n  return vec2(d, id);\n}\n\nvec3 normal(vec3 p) {\n  vec2 e = vec2(0.0015, 0.0);\n  return normalize(vec3(\n    map(p + e.xyy).x - map(p - e.xyy).x,\n    map(p + e.yxy).x - map(p - e.yxy).x,\n    map(p + e.yyx).x - map(p - e.yyx).x\n  ));\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;\n  vec3 ro = vec3(0.0, 0.35, 2.4);\n  vec3 rd = normalize(vec3(uv, -1.5));\n  float t = 0.0, id = -1.0;\n  for (int i = 0; i < 70; i++) {\n    vec2 h = map(ro + rd * t);\n    if (h.x < 0.001 || t > 10.0) { id = h.y; break; }\n    t += h.x;\n  }\n  vec3 sky = mix(vec3(0.75, 0.85, 0.95), vec3(0.4, 0.6, 0.9), uv.y * 0.5 + 0.4);\n  vec3 col = sky;\n  if (t < 10.0) {\n    vec3 p = ro + rd * t;\n    vec3 n = normal(p);\n    vec3 l = normalize(vec3(0.4, 0.8, 0.35));\n    float dif = max(dot(n, l), 0.0);\n    vec3 matc = vec3(0.95, 0.55, 0.2);\n    if (id > 1.5 && id < 2.5) {\n      matc = mix(vec3(0.35, 0.55, 0.28), vec3(0.5, 0.7, 0.35), step(0.0, sin(p.x * 8.0) * sin(p.z * 8.0)));\n    } else if (id > 2.5 && id < 3.5) matc = vec3(0.95);\n    else if (id > 3.5) matc = vec3(0.08);\n    col = matc * (0.25 + 0.75 * dif);\n    float jump = abs(sin(iTime * 3.2));\n    vec2 sh = p.xz;\n    float shadow = smoothstep(0.55, 0.12, length(sh) + jump * 0.15);\n    if (id > 1.5 && id < 2.5) col *= 1.0 - 0.45 * shadow;\n  }\n  fragColor = vec4(pow(col, vec3(0.92)), 1.0);\n}\n","mandelbulb":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// Mandelbulb (power 8): distance estimate, orbit-trap color. Drag to orbit.\n\nfloat mandelDE(vec3 pos, out float trap) {\n  vec3 z = pos;\n  float dr = 1.0, r = 0.0;\n  trap = 1e10;\n  for (int i = 0; i < 7; i++) {\n    r = length(z);\n    if (r > 2.0) break;\n    float th = acos(clamp(z.y / r, -1.0, 1.0));\n    float ph = atan(z.z, z.x);\n    float zr = pow(r, 8.0);\n    dr = pow(r, 7.0) * 8.0 * dr + 1.0;\n    th *= 8.0;\n    ph *= 8.0;\n    z = zr * vec3(sin(th) * cos(ph), cos(th), sin(th) * sin(ph)) + pos;\n    trap = min(trap, length(z));\n  }\n  return 0.5 * log(r) * r / dr;\n}\n\nvec3 normal(vec3 p) {\n  vec2 e = vec2(0.0012, 0.0);\n  float t;\n  return normalize(vec3(\n    mandelDE(p + e.xyy, t) - mandelDE(p - e.xyy, t),\n    mandelDE(p + e.yxy, t) - mandelDE(p - e.yxy, t),\n    mandelDE(p + e.yyx, t) - mandelDE(p - e.yyx, t)\n  ));\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;\n  float ang = (iMouse.z > 0.0) ? (iMouse.x / iResolution.x) * 6.28318 : iTime * 0.12;\n  vec3 ro = vec3(2.4 * sin(ang), 0.55, 2.4 * cos(ang));\n  vec3 ww = normalize(-ro);\n  vec3 uu = normalize(cross(ww, vec3(0, 1, 0)));\n  vec3 vv = cross(uu, ww);\n  vec3 rd = normalize(uv.x * uu + uv.y * vv + 1.8 * ww);\n\n  float t = 0.0, trap = 0.0, hit = 0.0;\n  for (int i = 0; i < 90; i++) {\n    float d = mandelDE(ro + rd * t, trap);\n    if (d < 0.001) { hit = 1.0; break; }\n    t += clamp(d, 0.002, 0.25);\n    if (t > 8.0) break;\n  }\n\n  vec3 col = vec3(0.02, 0.03, 0.06) + vec3(0.04, 0.05, 0.1) * (uv.y + 0.5);\n  if (hit > 0.5) {\n    vec3 p = ro + rd * t;\n    vec3 n = normal(p);\n    vec3 l = normalize(vec3(0.6, 0.7, 0.3));\n    float dif = max(dot(n, l), 0.0);\n    float fre = pow(1.0 - max(dot(n, -rd), 0.0), 3.0);\n    vec3 matc = 0.5 + 0.5 * cos(vec3(0.2, 0.5, 0.9) + trap * 4.5 + vec3(0.0, 2.0, 4.0));\n    col = matc * (0.18 + 0.85 * dif) + vec3(0.9, 0.95, 1.0) * fre * 0.35;\n  }\n  fragColor = vec4(pow(col, vec3(0.9)), 1.0);\n}\n","mandelbrot":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// Mandelbrot zoom. Click/drag to pick a zoom target (else a known bulb).\n\nvec3 pal(float t) {\n  return 0.5 + 0.5 * cos(6.2831853 * (vec3(0.0, 0.15, 0.25) + t * vec3(1.0, 0.8, 0.6) + vec3(0.0, 0.33, 0.67)));\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;\n  vec2 target = vec2(-0.743643887037151, 0.131825904205330);\n  if (iMouse.z > 0.0) {\n    vec2 m = (iMouse.xy - 0.5 * iResolution.xy) / iResolution.y;\n    target = m * 2.2 + vec2(-0.5, 0.0);\n  }\n  float zoom = exp(-mod(iTime * 0.22, 8.0));\n  vec2 c = target + uv * (2.4 * zoom);\n  vec2 z = vec2(0.0);\n  float i, n = 80.0;\n  for (i = 0.0; i < 80.0; i++) {\n    z = vec2(z.x * z.x - z.y * z.y, 2.0 * z.x * z.y) + c;\n    if (dot(z, z) > 16.0) break;\n  }\n  float v = i - log2(log2(dot(z, z))) + 4.0;\n  vec3 col = (i >= n) ? vec3(0.0) : pal(v * 0.06 + iTime * 0.04);\n  fragColor = vec4(col, 1.0);\n}\n","julia":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// Julia set (quadratic). Drag to move c. Palette cycles slowly.\n\nvec3 pal(float t) {\n  return 0.55 + 0.45 * cos(6.2831853 * (t + vec3(0.0, 0.27, 0.57)));\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;\n  vec2 z = uv * 1.65;\n  vec2 c = vec2(-0.4 + 0.3 * sin(iTime * 0.23), 0.6 * cos(iTime * 0.17));\n  if (iMouse.z > 0.0) {\n    c = (iMouse.xy - 0.5 * iResolution.xy) / iResolution.y;\n  }\n  float i, n = 70.0;\n  for (i = 0.0; i < 70.0; i++) {\n    z = vec2(z.x * z.x - z.y * z.y, 2.0 * z.x * z.y) + c;\n    if (dot(z, z) > 16.0) break;\n  }\n  float v = i - log2(log2(max(dot(z, z), 1.0001))) + 4.0;\n  vec3 col = (i >= n) ? vec3(0.02, 0.02, 0.04) : pal(v * 0.05);\n  fragColor = vec4(col, 1.0);\n}\n","menger":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// Menger sponge: recursive box fold, orbit camera.\n\nfloat sdBox(vec3 p, vec3 b) {\n  vec3 q = abs(p) - b;\n  return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0);\n}\n\nfloat menger(vec3 p) {\n  float d = sdBox(p, vec3(1.0));\n  float s = 1.0;\n  for (int i = 0; i < 4; i++) {\n    vec3 a = mod(p * s, 2.0) - 1.0;\n    s *= 3.0;\n    vec3 r = abs(1.0 - 3.0 * abs(a));\n    float da = max(r.x, r.y);\n    float db = max(r.y, r.z);\n    float dc = max(r.z, r.x);\n    float c = (min(da, min(db, dc)) - 1.0) / s;\n    d = max(d, c);\n  }\n  return d;\n}\n\nvec3 normal(vec3 p) {\n  vec2 e = vec2(0.0015, 0.0);\n  return normalize(vec3(\n    menger(p + e.xyy) - menger(p - e.xyy),\n    menger(p + e.yxy) - menger(p - e.yxy),\n    menger(p + e.yyx) - menger(p - e.yyx)\n  ));\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;\n  float ang = (iMouse.z > 0.0) ? (iMouse.x / iResolution.x) * 6.28318 : iTime * 0.18;\n  float elev = 0.45 + 0.15 * sin(iTime * 0.3);\n  vec3 ro = vec3(2.8 * sin(ang) * cos(elev), 2.8 * sin(elev), 2.8 * cos(ang) * cos(elev));\n  vec3 ww = normalize(-ro);\n  vec3 uu = normalize(cross(ww, vec3(0, 1, 0)));\n  vec3 vv = cross(uu, ww);\n  vec3 rd = normalize(uv.x * uu + uv.y * vv + 1.7 * ww);\n\n  float t = 0.0, hit = 0.0;\n  for (int i = 0; i < 90; i++) {\n    float d = menger(ro + rd * t);\n    if (d < 0.001) { hit = 1.0; break; }\n    t += d;\n    if (t > 12.0) break;\n  }\n\n  vec3 col = vec3(0.03, 0.04, 0.07) + vec3(0.08) * (uv.y + 0.4);\n  if (hit > 0.5) {\n    vec3 p = ro + rd * t;\n    vec3 n = normal(p);\n    vec3 l = normalize(vec3(0.5, 0.8, 0.25));\n    float dif = max(dot(n, l), 0.0);\n    float ao = 0.55 + 0.45 * n.y;\n    vec3 matc = 0.5 + 0.5 * cos(vec3(0.4, 0.7, 1.1) + n.xzy * 1.8 + vec3(0.0, 2.1, 4.2));\n    col = matc * (0.15 + 0.85 * dif) * ao;\n    col += vec3(1.0) * pow(max(dot(n, normalize(l - rd)), 0.0), 40.0) * 0.2;\n  }\n  fragColor = vec4(pow(col, vec3(0.9)), 1.0);\n}\n","metaballs":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// Ray-marched metaballs: polynomial blob field, fake refraction tint.\n\nfloat blob(vec3 p, vec3 c, float r) {\n  float d = length(p - c);\n  return r * r / max(d * d, 1e-4);\n}\n\nfloat field(vec3 p) {\n  float t = iTime;\n  float f = 0.0;\n  f += blob(p, vec3(0.55 * sin(t * 0.9), 0.35 * cos(t * 1.1), 0.2 * sin(t * 0.7)), 0.42);\n  f += blob(p, vec3(0.5 * cos(t * 0.8 + 1.2), 0.4 * sin(t * 1.3), 0.25 * cos(t * 0.6)), 0.38);\n  f += blob(p, vec3(0.45 * sin(t * 1.2 + 2.0), 0.3 * cos(t * 0.9 + 0.4), 0.3 * sin(t * 1.05)), 0.36);\n  f += blob(p, vec3(0.0, -0.15, 0.0), 0.28);\n  return f;\n}\n\nfloat map(vec3 p) {\n  return 1.0 - field(p);\n}\n\nvec3 normal(vec3 p) {\n  vec2 e = vec2(0.002, 0.0);\n  return normalize(vec3(\n    map(p + e.xyy) - map(p - e.xyy),\n    map(p + e.yxy) - map(p - e.yxy),\n    map(p + e.yyx) - map(p - e.yyx)\n  ));\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;\n  vec3 ro = vec3(0.0, 0.1, 2.6);\n  vec3 rd = normalize(vec3(uv, -1.5));\n  float t = 0.0, hit = 0.0;\n  for (int i = 0; i < 70; i++) {\n    float d = map(ro + rd * t);\n    if (d < 0.002) { hit = 1.0; break; }\n    t += d * 0.55;\n    if (t > 6.0) break;\n  }\n  vec3 bg = mix(vec3(0.06, 0.07, 0.1), vec3(0.2, 0.22, 0.28), uv.y * 0.5 + 0.5);\n  vec3 col = bg;\n  if (hit > 0.5) {\n    vec3 p = ro + rd * t;\n    vec3 n = normal(p);\n    vec3 l = normalize(vec3(0.4, 0.7, 0.5));\n    float dif = max(dot(n, l), 0.0);\n    float spec = pow(max(dot(n, normalize(l - rd)), 0.0), 64.0);\n    float fre = pow(1.0 - max(dot(n, -rd), 0.0), 3.0);\n    vec3 matc = mix(vec3(0.15, 0.55, 0.85), vec3(0.95, 0.35, 0.55), 0.5 + 0.5 * n.y);\n    col = matc * (0.2 + 0.8 * dif) + vec3(1.0) * spec * 0.55 + bg * fre * 0.45;\n  }\n  fragColor = vec4(pow(col, vec3(0.92)), 1.0);\n}\n","tunnel":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// Polar tunnel: 1/r depth, stripes, fog. Demo-scene staple.\n\nfloat hash12(vec2 p) {\n  vec3 p3 = fract(vec3(p.xyx) * 0.1031);\n  p3 += dot(p3, p3.yzx + 33.33);\n  return fract((p3.x + p3.y) * p3.z);\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;\n  float r = length(p);\n  float a = atan(p.y, p.x);\n  vec2 uv = vec2(a / 3.14159265, 0.35 / max(r, 0.02) + iTime * 0.55);\n  float stripes = 0.5 + 0.5 * sin(uv.x * 18.0 + uv.y * 4.0);\n  float tiles = step(0.5, fract(uv.x * 8.0)) * step(0.5, fract(uv.y * 3.0));\n  vec3 col = mix(vec3(0.05, 0.06, 0.1), vec3(0.9, 0.35, 0.15), stripes);\n  col = mix(col, vec3(0.15, 0.45, 0.85), tiles * 0.65);\n  col += 0.12 * hash12(floor(uv * vec2(32.0, 12.0)));\n  col *= smoothstep(0.0, 0.18, r);\n  col *= exp(-0.15 / max(r, 0.04));\n  vec3 fog = vec3(0.02, 0.02, 0.04);\n  col = mix(fog, col, smoothstep(0.0, 0.22, r));\n  fragColor = vec4(col, 1.0);\n}\n","terrain":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// fBm height-field terrain, sky, fog. Drag to look around.\n// Genre made famous on Shadertoy; this implementation is original.\n\nfloat hash12(vec2 p) {\n  vec3 p3 = fract(vec3(p.xyx) * 0.1031);\n  p3 += dot(p3, p3.yzx + 33.33);\n  return fract((p3.x + p3.y) * p3.z);\n}\nfloat noise(vec2 p) {\n  vec2 i = floor(p), f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1,0)), u.x),\n             mix(hash12(i + vec2(0,1)), hash12(i + vec2(1,1)), u.x), u.y);\n}\nfloat fbm(vec2 p) {\n  float v = 0.0, a = 0.5;\n  mat2 m = mat2(1.6, 1.2, -1.2, 1.6);\n  for (int i = 0; i < 6; i++) { v += a * noise(p); p = m * p; a *= 0.5; }\n  return v;\n}\n\nfloat height(vec2 xz) {\n  return fbm(xz * 0.12) * 2.4 + 0.35 * fbm(xz * 0.55);\n}\n\nvec3 sky(vec3 rd) {\n  vec3 c = mix(vec3(0.62, 0.72, 0.88), vec3(0.22, 0.42, 0.75), pow(max(rd.y, 0.0), 0.5));\n  vec3 sun = normalize(vec3(0.4, 0.18, 0.7));\n  c += vec3(1.0, 0.8, 0.45) * pow(max(dot(rd, sun), 0.0), 180.0);\n  return c;\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;\n  float yaw = (iMouse.z > 0.0) ? (iMouse.x / iResolution.x - 0.5) * 2.5 : 0.2;\n  vec3 ro = vec3(iTime * 0.7, 1.8, iTime * 0.35);\n  ro.y += height(ro.xz) * 0.15 + 0.9;\n  vec3 fwd = normalize(vec3(sin(yaw), -0.22, cos(yaw)));\n  vec3 right = normalize(cross(fwd, vec3(0, 1, 0)));\n  vec3 up = cross(right, fwd);\n  vec3 rd = normalize(fwd + uv.x * right + uv.y * up);\n\n  float t = 0.0, hit = 0.0;\n  for (int i = 0; i < 90; i++) {\n    vec3 p = ro + rd * t;\n    float d = p.y - height(p.xz);\n    if (d < 0.02) { hit = 1.0; break; }\n    t += max(d * 0.45, 0.04);\n    if (t > 55.0) break;\n  }\n\n  vec3 col = sky(rd);\n  if (hit > 0.5) {\n    vec3 p = ro + rd * t;\n    float e = 0.08;\n    vec3 n = normalize(vec3(\n      height(p.xz - vec2(e, 0.0)) - height(p.xz + vec2(e, 0.0)),\n      2.0 * e,\n      height(p.xz - vec2(0.0, e)) - height(p.xz + vec2(0.0, e))\n    ));\n    vec3 l = normalize(vec3(0.4, 0.7, 0.35));\n    float dif = max(dot(n, l), 0.0);\n    vec3 rock = mix(vec3(0.22, 0.2, 0.16), vec3(0.4, 0.38, 0.3), n.y);\n    vec3 grass = vec3(0.18, 0.32, 0.12);\n    vec3 matc = mix(rock, grass, smoothstep(0.45, 0.85, n.y));\n    matc = mix(matc, vec3(0.85, 0.88, 0.9), smoothstep(1.6, 2.2, p.y));\n    col = matc * (0.22 + 0.78 * dif);\n    col = mix(sky(rd), col, exp(-0.025 * t));\n  }\n  fragColor = vec4(pow(col, vec3(0.92)), 1.0);\n}\n","volume-clouds":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// Cheap volumetric clouds: density along a sky ray, beer attenuation.\n// Genre made famous on Shadertoy; this implementation is original.\n\nfloat hash12(vec2 p) {\n  vec3 p3 = fract(vec3(p.xyx) * 0.1031);\n  p3 += dot(p3, p3.yzx + 33.33);\n  return fract((p3.x + p3.y) * p3.z);\n}\nfloat noise(vec3 p) {\n  vec3 i = floor(p), f = fract(p);\n  f = f * f * (3.0 - 2.0 * f);\n  vec2 a = i.xy + i.z * vec2(17.0, 29.0);\n  float n0 = mix(mix(hash12(a), hash12(a + vec2(1,0)), f.x),\n                 mix(hash12(a + vec2(0,1)), hash12(a + vec2(1,1)), f.x), f.y);\n  a += vec2(17.0, 29.0);\n  float n1 = mix(mix(hash12(a), hash12(a + vec2(1,0)), f.x),\n                 mix(hash12(a + vec2(0,1)), hash12(a + vec2(1,1)), f.x), f.y);\n  return mix(n0, n1, f.z);\n}\nfloat fbm(vec3 p) {\n  float v = 0.0, a = 0.5;\n  for (int i = 0; i < 5; i++) { v += a * noise(p); p = p * 2.05 + 11.3; a *= 0.5; }\n  return v;\n}\n\nvec3 sky(vec3 rd) {\n  vec3 c = mix(vec3(0.55, 0.7, 0.95), vec3(0.15, 0.32, 0.7), pow(max(rd.y, 0.0), 0.55));\n  vec3 sun = normalize(vec3(0.35, 0.25, 0.7));\n  c += vec3(1.0, 0.85, 0.5) * pow(max(dot(rd, sun), 0.0), 160.0);\n  return c;\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;\n  vec3 ro = vec3(0.0, 0.6, iTime * 0.12);\n  vec3 rd = normalize(vec3(uv, 1.15));\n  vec3 col = sky(rd);\n  if (rd.y > 0.02) {\n    float t0 = (1.2 - ro.y) / rd.y;\n    float t1 = (2.4 - ro.y) / rd.y;\n    float dens = 0.0;\n    vec3 sun = normalize(vec3(0.35, 0.25, 0.7));\n    for (int i = 0; i < 18; i++) {\n      float fi = (float(i) + 0.5) / 18.0;\n      float t = mix(t0, t1, fi);\n      vec3 p = ro + rd * t;\n      float n = fbm(p * 0.55 + vec3(iTime * 0.05, 0.0, 0.0));\n      float d = smoothstep(0.42, 0.78, n);\n      dens += d * 0.085;\n    }\n    dens = 1.0 - exp(-dens * 2.2);\n    float light = 0.55 + 0.45 * max(dot(rd, sun), 0.0);\n    vec3 cloud = mix(vec3(0.55, 0.6, 0.7), vec3(1.0), light);\n    col = mix(col, cloud, dens * smoothstep(0.02, 0.12, rd.y));\n  }\n  fragColor = vec4(col, 1.0);\n}\n","voxels":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// Voxel DDA through a hashed height field. Drag to look.\n\nfloat hash12(vec2 p) {\n  vec3 p3 = fract(vec3(p.xyx) * 0.1031);\n  p3 += dot(p3, p3.yzx + 33.33);\n  return fract((p3.x + p3.y) * p3.z);\n}\n\nfloat voxelH(vec2 c) {\n  float h = hash12(c);\n  if (h < 0.16) return 1.0;\n  return 1.0 + floor(h * 5.0);\n}\n\nvec3 voxelAlbedo(vec2 c, float y) {\n  float rnd = hash12(c + 19.7);\n  vec3 grass = vec3(0.28, 0.55, 0.18);\n  vec3 dirt = vec3(0.45, 0.32, 0.18);\n  vec3 stone = vec3(0.45, 0.46, 0.48);\n  vec3 water = vec3(0.12, 0.32, 0.55);\n  if (hash12(c) < 0.16) return water;\n  if (y > voxelH(c) - 0.5) return mix(grass, dirt, rnd * 0.35);\n  return mix(stone, dirt, rnd);\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;\n  float yaw = (iMouse.z > 0.0) ? (iMouse.x / iResolution.x - 0.5) * 3.0 : iTime * 0.15;\n  vec3 ro = vec3(iTime * 1.4, 8.5, 4.0 + iTime * 0.4);\n  vec3 fwd = normalize(vec3(sin(yaw), -0.45, cos(yaw)));\n  vec3 right = normalize(cross(fwd, vec3(0, 1, 0)));\n  vec3 up = cross(right, fwd);\n  vec3 rd = normalize(fwd + uv.x * right + uv.y * up);\n\n  vec3 pos = floor(ro);\n  vec3 delta = abs(1.0 / max(abs(rd), vec3(1e-4)));\n  vec3 stepv = sign(rd);\n  vec3 tmax = (stepv * (0.5 - fract(ro)) + 0.5) * delta;\n\n  vec3 col = mix(vec3(0.55, 0.72, 0.95), vec3(0.3, 0.5, 0.85), uv.y * 0.5 + 0.5);\n  vec3 nrm = vec3(0.0);\n  float hit = 0.0;\n  for (int i = 0; i < 80; i++) {\n    if (pos.y < voxelH(pos.xz) && pos.y >= 0.0) {\n      hit = 1.0;\n      break;\n    }\n    if (tmax.x < tmax.y) {\n      if (tmax.x < tmax.z) { pos.x += stepv.x; tmax.x += delta.x; nrm = vec3(-stepv.x, 0, 0); }\n      else { pos.z += stepv.z; tmax.z += delta.z; nrm = vec3(0, 0, -stepv.z); }\n    } else {\n      if (tmax.y < tmax.z) { pos.y += stepv.y; tmax.y += delta.y; nrm = vec3(0, -stepv.y, 0); }\n      else { pos.z += stepv.z; tmax.z += delta.z; nrm = vec3(0, 0, -stepv.z); }\n    }\n    if (pos.y < -1.0 || pos.y > 14.0) break;\n  }\n\n  if (hit > 0.5) {\n    vec3 l = normalize(vec3(0.4, 0.8, 0.3));\n    float dif = max(dot(nrm, l), 0.18);\n    col = voxelAlbedo(pos.xz, pos.y) * dif;\n    float dist = length(pos + 0.5 - ro);\n    col = mix(vec3(0.55, 0.7, 0.9), col, exp(-0.028 * dist));\n  }\n  fragColor = vec4(pow(col, vec3(0.92)), 1.0);\n}\n","warp":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// Domain-warped cosine palette. Can flicker — warn the room.\n// Technique popularized on Shadertoy; this implementation is original.\n\nfloat hash12(vec2 p) {\n  vec3 p3 = fract(vec3(p.xyx) * 0.1031);\n  p3 += dot(p3, p3.yzx + 33.33);\n  return fract((p3.x + p3.y) * p3.z);\n}\nfloat noise(vec2 p) {\n  vec2 i = floor(p), f = fract(p);\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(mix(hash12(i), hash12(i + vec2(1,0)), u.x),\n             mix(hash12(i + vec2(0,1)), hash12(i + vec2(1,1)), u.x), u.y);\n}\nfloat fbm(vec2 p) {\n  float v = 0.0, a = 0.5;\n  mat2 m = mat2(1.6, 1.2, -1.2, 1.6);\n  for (int i = 0; i < 6; i++) { v += a * noise(p); p = m * p; a *= 0.5; }\n  return v;\n}\n\nvec3 pal(float t) {\n  return 0.5 + 0.5 * cos(6.2831853 * (t + vec3(0.0, 0.33, 0.67)));\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;\n  vec2 q = p;\n  q += 0.35 * vec2(fbm(q * 2.0 + iTime * 0.12), fbm(q * 2.0 + 4.2));\n  q += 0.2 * vec2(fbm(q * 3.5 - iTime * 0.08), fbm(q * 3.5 + 7.1));\n  float n = fbm(q * 2.4);\n  vec3 col = pal(n + iTime * 0.06 + length(p) * 0.15);\n  col *= 0.75 + 0.25 * n;\n  fragColor = vec4(col, 1.0);\n}\n","heart":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// 2D heart SDF with a beat and a soft glow. Beginner favorite.\n\nfloat heart(vec2 p) {\n  p.x = abs(p.x);\n  if (p.x + p.y > 1.0) return length(p - vec2(0.25, 0.75)) - 0.35355339;\n  return sqrt(min(dot(p, p), dot(p - vec2(0.0, 1.0), p - vec2(0.0, 1.0)))) * sign(p.x - p.y);\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;\n  float beat = 1.0 + 0.08 * sin(iTime * 6.0) + 0.04 * sin(iTime * 12.0);\n  p.y += 0.12;\n  p /= 0.55 * beat;\n  float d = heart(p);\n  float fill = 1.0 - smoothstep(0.0, 0.01, d);\n  float glow = exp(-3.5 * max(d, 0.0));\n  vec3 bg = mix(vec3(0.08, 0.04, 0.08), vec3(0.18, 0.06, 0.1), 0.5 + 0.5 * p.y);\n  vec3 red = mix(vec3(0.55, 0.05, 0.12), vec3(0.95, 0.2, 0.28), fill * (0.6 + 0.4 * (0.5 - p.y)));\n  vec3 col = mix(bg, red, fill);\n  col += vec3(0.8, 0.15, 0.25) * glow * 0.45 * (1.0 - fill);\n  float spec = smoothstep(0.12, 0.0, length(p - vec2(-0.18, 0.22))) * fill;\n  col += spec * 0.35;\n  fragColor = vec4(col, 1.0);\n}\n","neon":"// IGWT teaching shader. Paste into https://www.shadertoy.com (Image tab).\n// 2D SDF neon: distance-as-glow, cheap bloom. Front-page look.\n\nfloat sdCircle(vec2 p, float r) { return length(p) - r; }\nfloat sdSegment(vec2 p, vec2 a, vec2 b) {\n  vec2 pa = p - a, ba = b - a;\n  float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);\n  return length(pa - ba * h);\n}\nfloat sdBox(vec2 p, vec2 b) {\n  vec2 d = abs(p) - b;\n  return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0);\n}\n\nvec3 glow(float d, vec3 c, float k) {\n  return c * (k / (abs(d) + k));\n}\n\nvoid mainImage(out vec4 fragColor, in vec2 fragCoord) {\n  vec2 p = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;\n  float t = iTime;\n  vec3 col = vec3(0.02, 0.03, 0.05);\n\n  float ring = sdCircle(p, 0.42 + 0.02 * sin(t * 2.0));\n  col += glow(ring, vec3(0.2, 0.85, 1.0), 0.012);\n\n  vec2 q = p;\n  float a = t * 0.7;\n  q = mat2(cos(a), -sin(a), sin(a), cos(a)) * q;\n  float hex = sdBox(q, vec2(0.22)) - 0.04;\n  col += glow(hex, vec3(1.0, 0.25, 0.7), 0.01);\n\n  float bar = sdSegment(p, vec2(-0.55, -0.28), vec2(0.55, -0.28 + 0.08 * sin(t * 3.0))) - 0.012;\n  col += glow(bar, vec3(1.0, 0.85, 0.2), 0.008);\n\n  float d2 = sdCircle(p - vec2(0.55 * cos(t), 0.35 * sin(t * 1.3)), 0.06);\n  col += glow(d2, vec3(0.4, 1.0, 0.5), 0.01);\n\n  col += col * col * 0.35;\n  fragColor = vec4(col, 1.0);\n}\n"};
